css:
@page {
        size: A4 landscape;
        margin: 10mm;
    }

    body {
        font-family: Arial, sans-serif;
        font-size: 12px;
    }

    table {
        border-collapse: collapse;
        width: 100%;
    }

    .section-title {
        font-weight: bold;
        font-size: 13px;
    }


.print-heading{
    display:none;
}
 .text-center h4 {
    display: none;
}

 .text-center  {
    display: none;
}


* {
    color: black;
}

.print-format td, .print-format th{
    padding: 0 !important;
}

.print-format{
    orientation:landscape;
}

.print-heading {
    display: none;
}

.page-header,
.page-header-space {
    height: 0px;
}

.page-footer,
.page-footer-space {
    margin-top: 90px;
    border-right: 0;
    border-left: 0;

}

/*.page-footer {*/
/*    position: fixed;*/
/*    bottom: 0;*/
/*    text-align: center !important;*/
/*    width: 100%;*/
/*    padding-top:50px !important;*/
    /*margin: auto;*/

/*}*/

.page-break-before {
    page-break-before: always;
}


.page-header {
    position: fixed;
    top: 0mm;
    display: block;
    width: 99.4%;
    border-bottom: 0 !important;
    color: #ffffff;
    margin-left: 0px !important;
    padding-left: 0 !important;
}

.print-format .print-format-preview {
    padding-left: 0px !important;
}

.scope-work {
    margin-inline: 60px;
    margin-bottom: 30px;

}

.scope-work-table {
    border: 1px solid black;
    color: black !important;

}

.scope-work-table {
    width: 100%;
    border-collapse: collapse;

}

.scope-work-table td {
    text-align: start;
    vertical-align: top;
}

.scope-work-table th {
    background-color: #c9daf8;
    color: black !important;
    text-align: center;
    font-weight: bold !important;

}

.scope-work-table th:nth-child(1) {
    width: 20%;
    min-width: 150px;
}

.scope-work-table th:nth-child(2) {
    width: 20%;
    min-width: 150px;
}

.scope-work-table th:nth-child(3) {
    width: 60%;
}

.test-table {
    color: black !important;
    width: 100%;
    border-collapse: collapse;

}

.test-table td {
    text-align: left;
    border-bottom: 1px solid black;
    border-left: 1px solid black;
    border-right: 1px solid black;
}

.test-table td:nth-child(1) {
    width: 20%;
    min-width: 150px;
}

.test-table td:nth-child(2) {
    width: 20%;
    min-width: 150px;
}

.test-table td:nth-child(3) {
    width: 60%;
}



@page {
    size: A4 potrait;
    margin: 10mm;
    

}

@media print {
    thead {
        display: table-header-group;
    }

    tfoot {
        display: table-footer-group;
    }

    /*.page-header,*/
    .page-header-space {
        /*height: 50px;*/
        border-bottom: 0 !important;
    }

    /*.page-header,*/
    .page-footer-space {
        height:-100px;

    }

    @media print {
        .page-break-before {
            page-break-before: always;
        }

        .page-header {
            display: block;
        }

        .print-format .print-format-preview {
            padding-left: 0px !important;
            padding-top: 0px !important;
        }

    }

    button {
        display: none;
    }

    body {
        margin: 0;
    }
}

.page-header {
    margin: 0px !important;
    padding: 0 !important;
}

.text-center h4 {
    display: none;
}

body {
        counter-reset: page;
    }


.page-no::after {
        counter-increment: page;
        content: "Page " counter(page);
    }
    
    
.print-format th {
    color: black;
    font-weight: normal;
    border-bottom-width: 1px !important;
}
    
.print-format p {
    margin: 0px 0px -2px;
}

.ql-editor.read-mode {
     overflow: hidden !important;
     
}

html:
{%- from "templates/print_formats/standard_macros.html" import add_header, render_field -%}
<html>

        {% set company = frappe.db.get_value('Address', doc.company_address, ['address_title', 'address_type', 'address_line1', 'address_line2','city', 'country', 'state', 'pincode', 'gstin','gst_state','gst_state_number']) %}
        {% set pan_no = frappe.db.get_value('Company', doc.company, ['pan_details','cin_number','website','email','phone_no','fax']) %}
        {% set warehouse = frappe.db.get_value('Address', doc.dispatch_address_name, ['address_title', 'address_type', 'address_line1', 'address_line2','city', 'country', 'state', 'pincode', 'gstin','gst_state','gst_state_number']) %}

        <header>
            <table style="border: 1px solid black; width: 100%; border-collapse: collapse; table-layout: fixed;">
                <tr>
                    <td style="width: 15%;">
                        {% set einvoice = frappe.db.get_value('Sales Invoice', doc.name, ['irn']) %}
                        {% if einvoice and einvoice.strip() %}
                            {% set imagename = "/invoice/qr_" + doc.irn + ".png" %}
                            <img style="width: 130px; height: 140px;margin-top:5px;margin-right:5px;margin-bottom:5px;margin-left:5px;" src="{{ imagename }}" alt="QR Code">
                        {% else %}
                            <div></div>
                        {% endif %}
                    </td>
                    <td style="width: 85%;">
                        <table style="width: 100%; border-collapse: collapse;">
                            <tr>
                                <!-- Center Section -->
                                <td style="width: 50%; text-align: center; padding: 10px;">
                                    <p style="margin: 0; font-size: 20px;"><b>{{ doc.company }}</b></p>
                                    <p style="font-size: 15px;">{{ warehouse[2] or '' }} {{ warehouse[3] or '' }}</p>
                                    <p style="font-size: 15px;">{{ warehouse[4] or '' }}, {{ warehouse[5] or '' }}, {{ warehouse[6] or '' }} - {{warehouse[7] or '' }}</p>
                                    <p style="font-size: 15px;">GSTIN: {{ doc.company_gstin or '' }} State Code - {{ warehouse[10] or '24' }}</p>
                                </td>

                                <td style="width: 5%;">
                                </td>

                                <td style="width: 20%;">
                                    <br>
                                    <p style="font-size: 17px;">☐ Original For Buyers</p>
                                    <p style="font-size: 17px;">☐ Duplicate for Transporter</p>
                                    <p style="font-size: 17px;">☐ Triplicate For Supplier</p>
                                </td>
                            </tr>
                            <tr>
                                <td colspan="3" style="padding: 0;">
                                    <hr style="border: none; border-bottom: 1px dotted #000; margin: 5px 0;">
                                </td>
                            </tr>
                            <tr>
                                <!-- Right Section -->
                                <td colspan="3" style="text-align: center; padding: 3px;">
                                    <p style="margin: 0; font-size: 15px; font-weight: bold; display: inline-block; border-bottom: 1px solid #000; padding-bottom: 1px;">
                                        <b>TAX INVOICE - {{ doc.name }} DATED - {{ frappe.format_date(doc.posting_date, "MMM dd, yyyy") if doc.posting_date else '' }}</b></p>
                                    <p style="margin: 0; font-size: 13px; padding-top: 1px;">{{ doc.irn }}</p>
                                </td>
                            </tr>

                        </table>
                    </td>
                </tr>
            </table>
        </header>

        <table style="width: 100%; border-collapse: separate; border-spacing: 10px; text-align: center; margin-top: 2px;">
            <tr>
                <td style="width: 33.33%; border: 1px solid #000; border-radius: 10px; padding: 10px;">
                    {% if doc.customer_address and doc.customer_address.strip() %}
                        <p style="margin: 0; font-size: 13px;"><b>BILL TO / PLACE OF SUPPLY</b></p>
                        <p style="margin: 0; font-size: 12px;"><b>{{ doc.customer_name or '' }}</b></p>
                        {% set bill_to_address = frappe.db.get_value('Address',doc.customer_address, ['address_title', 'address_type', 'address_line1','address_line2', 'city', 'country', 'state','pincode', 'gstin','gst_state','gst_state_number']) %}
                        {% if bill_to_address %}
                            <p style="font-size: 10px;">{{ bill_to_address[2] or '' }} {{ bill_to_address[3] or '' }}</p>
                            <p style="font-size: 10px;">{{ bill_to_address[4] or '' }}, {{ bill_to_address[5] or '' }}, {{ bill_to_address[6] or '' }} - {{bill_to_address[7] or '' }}</p>
                            <p style="font-size: 10px;">GSTIN: {{ bill_to_address[8] or '' }} State Code - {{ bill_to_address[10] or '' }}</p>
                        {% endif %}
                    {% endif %}
                </td>
                <td style="width: 33.33%; border: 1px solid #000; border-radius: 10px; padding: 10px;">
                    {% if doc.shipping_address_name and doc.shipping_address_name.strip() %}
                        <p style="margin: 0; font-size: 13px;"><b>SHIP TO / PLACE OF SUPPLY</b></p>
                        <p style="margin: 0; font-size: 12px;"><b>{{ doc.customer_name or '' }}</b></p>
                        {% set ship_to_address = frappe.db.get_value('Address',doc.shipping_address_name, ['address_title', 'address_type', 'address_line1','address_line2', 'city', 'country', 'state','pincode', 'gstin','gst_state','gst_state_number']) %}
                        {% if ship_to_address %}
                            <p style="font-size: 10px;">{{ ship_to_address[2] or '' }} {{ ship_to_address[3] or '' }}</p>
                            <p style="font-size: 10px;">{{ ship_to_address[4] or '' }}, {{ ship_to_address[5] or '' }}, {{ ship_to_address[6] or '' }} - {{ship_to_address[7] or '' }}</p>
                            <p style="font-size: 10px;">GSTIN: {{ ship_to_address[8] or '' }} State Code - {{ ship_to_address[10] or '' }}</p>
                        {% endif %}
                    {% endif %}
                </td>
                <td style="width: 33.33%; border: 1px solid #000; border-radius: 10px; padding: 0; text-align: left;">
                    <div style="padding: 10px 10px 10px 10px;">  <!-- left padding = 25px -->
                        <p style="font-size: 10px; margin: 2px 0;">E Way Bill Number:</p>
                        <p style="font-size: 10px; margin: 2px 0;">L R No. :{{ doc.tracking_number}}</p>
                        <p style="font-size: 10px; margin: 2px 0;">L R Date:</p>
                        {% set e_invoice_log = frappe.db.get_value("eInvoice Log", doc.irn, ("acknowledgement_number", "acknowledged_on"), as_dict=True) %}
                        {% if e_invoice_log %}
                            <p style="font-size: 10px; margin: 2px 0;">Ack No :{{ e_invoice_log["acknowledgement_number"] or '' }}</p>
                            {% if e_invoice_log["acknowledged_on"] %}
                                {% set ack_date_str = e_invoice_log["acknowledged_on"] | string %}

                                <p style="font-size: 10px; margin: 2px 0;">Ack Date :{{ ack_date_str.split(' ')[0] }}</p>
                                <p style="font-size: 10px; margin: 2px 0;">Customer PO No: {{ doc.po_no}}</p>
                                <p style="font-size: 10px; margin: 2px 0;">No. of Boxes:</p>
                            {% endif %}
                            <!-- <p style="font-size: 10px; margin: 2px 0;">Ack Date :{{ e_invoice_log["acknowledged_on"] or '' }}</p> -->
                        {% endif %}
                    </div>
                </td>
            </tr>
        </table>



        {% set company_state = company[9] or '' %}
        {% set customer_state = '' %}

        {% if doc.shipping_address_name %}
            {% set addr = frappe.db.get_value('Address', doc.shipping_address_name, ['gst_state']) %}
            {% if addr %}
                {% set customer_state = addr %}
            {% endif %}
        {% elif doc.customer_address %}
            {% set addr = frappe.db.get_value('Address', doc.customer_address, ['gst_state']) %}
            {% if addr %}
                {% set customer_state = addr %}
            {% endif %}
        {% endif %}


        {% set has_igst = false %}
        {% if company_state == customer_state %}
            {% set has_igst = false %}
        {% else %}
            {% set has_igst = true %}
        {% endif %}






        {% set ratewise_gst = {} %}
        {% set hsnwise_gst = {} %}

        <table style="width: 100%; border-collapse: collapse; font-size: 11px; text-align: center; margin-top: 5px;">
            <thead>
                <tr style="background-color: #f2f2f2; text-align: center;">
                    <th style="width: 7%; border: 1px solid #000; text-align: center; vertical-align: middle;">HSN<br>Code</th>
                    <th style="width: 40%; border: 1px solid #000; text-align: center; vertical-align: middle;">Material<br>Description</th>
                    <th style="width: 6%; border: 1px solid #000; text-align: center; vertical-align: middle;">MRP</th>
                    <th style="width: 6%; border: 1px solid #000; text-align: center; vertical-align: middle;">Qty</th>
                    <th style="width: 6%; border: 1px solid #000; text-align: center; vertical-align: middle;">Rate<br>(Rs.)</th>
                    <th style="width: 7%; border: 1px solid #000; text-align: center; vertical-align: middle;">Taxable<br>Amount</th>
                    <th style="width: 4%; border: 1px solid #000; text-align: center; vertical-align: middle;">GST %</th>
                    <th style="width: 5%; border: 1px solid #000; text-align: center; vertical-align: middle;">GST<br>(Rs.)</th>
                    <th style="width: 8%; border: 1px solid #000; text-align: center; vertical-align: middle;">Total<br>Amount</th>
                </tr>
            </thead>
            <tbody>
                {% for row in doc.items %}

                    <tr>
                        <td style="border: 1px solid #000; text-align: left;"><div style="padding-left: 5px;">{{ row.gst_hsn_code or '' }}</div></td>
                        <td style="border: 1px solid #000; text-align: left;"><div style="padding-left: 5px;">{{ row.item_name or '' }}</div></td>
                        {% set standard_rate = frappe.db.get_value("Item", row.item_code, "standard_rate") %}
                        <td style="border: 1px solid #000; text-align: right;"><div style="padding-right: 5px;">{{ frappe.format_value(standard_rate, doc.currency) if standard_rate else '' }}</div></td>
                        <td style="border: 1px solid #000; text-align: right;"><div style="padding-right: 5px;">{{ row.qty or 0 }}</div></td>
                        <td style="border: 1px solid #000; text-align: right;"><div style="padding-right: 5px;">{{ ("%.2f"|format(row.rate)) if row.rate else '' }}</div></td>
                        <td style="border: 1px solid #000; text-align: right;"><div style="padding-right: 5px;">{{ ("%.2f"|format(row.taxable_value)) if row.taxable_value else '' }}</div></td>

                        {% set gst_rate = 0 %}
                        {% set gst_value = 0 %}

                        {% if row.item_tax_template %}
                            <!-- {% set gst_rate = frappe.db.get_value("Item Tax Template Detail",{"parent": row.item_tax_template},"tax_rate") %} -->
                            {% set gst_rate = frappe.db.get_value("Item Tax Template",{"name": row.item_tax_template},"rate") %}

                            {% if row.net_amount %}
                                {% set gst_value = (row.base_amount * (gst_rate / 100)) | round(4) %}
                            {% endif %}



                            {% set cgst_rate = 0 %}
                            {% set sgst_rate = 0 %}
                            {% set igst_rate = 0 %}

                            {% set cgst_value = 0 %}
                            {% set sgst_value = 0 %}
                            {% set igst_value = 0 %}

                            {% if has_igst %}
                                {% set igst_rate = gst_rate %}
                                {% set igst_value = gst_value %}
                            {% else %}
                                {% set cgst_rate = gst_rate / 2 %}
                                {% set sgst_rate = gst_rate / 2 %}
                                {% set cgst_value = gst_value / 2 %}
                                {% set sgst_value = gst_value / 2 %}
                            {% endif %}


                            {% set key = gst_rate|string %}
                            {% if ratewise_gst.get(key) %}
                                {% set _ = ratewise_gst[key].update({
                                    "taxable": ratewise_gst[key]["taxable"] + (row.base_amount or 0),
                                    "cgst_rate": cgst_rate,
                                    "sgst_rate": sgst_rate,
                                    "igst_rate": igst_rate,
                                    "cgst_value": ratewise_gst[key]["cgst_value"] + cgst_value,
                                    "sgst_value": ratewise_gst[key]["sgst_value"] + sgst_value,
                                    "igst_value": ratewise_gst[key]["igst_value"] + igst_value,
                                    "tax": ratewise_gst[key]["tax"] + gst_value
                                }) %}
                            {% else %}
                                {% set _ = ratewise_gst.update({
                                    key: {
                                        "taxable": row.base_amount or 0,
                                        "cgst_rate": cgst_rate,
                                        "sgst_rate": sgst_rate,
                                        "igst_rate": igst_rate,
                                        "cgst_value": cgst_value,
                                        "sgst_value": sgst_value,
                                        "igst_value": igst_value,
                                        "tax": gst_value,
                                    }
                                }) %}
                            {% endif %}



                            {% set key_hsn = row.gst_hsn_code|string %}
                            {% if hsnwise_gst.get(key_hsn) %}
                                {% set _ = hsnwise_gst[key_hsn].update({
                                    "hsn": key_hsn,
                                    "qty": hsnwise_gst[key_hsn]["qty"] + (row.qty or 0),
                                    "cgst_rate": cgst_rate,
                                    "sgst_rate": sgst_rate,
                                    "igst_rate": igst_rate,
                                    "taxable": hsnwise_gst[key_hsn]["taxable"] + (row.taxable_value or 0),
                                    "cgst_value": hsnwise_gst[key_hsn]["cgst_value"] + cgst_value,
                                    "sgst_value": hsnwise_gst[key_hsn]["sgst_value"] + sgst_value,
                                    "igst_value": hsnwise_gst[key_hsn]["igst_value"] + igst_value,
                                    "tax": hsnwise_gst[key_hsn]["tax"] + gst_value,
                                    "invoice_value": hsnwise_gst[key_hsn]["invoice_value"] + (gst_value + row.taxable_value),
                                }) %}
                            {% else %}
                                {% set _ = hsnwise_gst.update({
                                    key_hsn: {
                                        "hsn": key_hsn,
                                        "qty": row.qty or 0,
                                        "cgst_rate": cgst_rate,
                                        "sgst_rate": sgst_rate,
                                        "igst_rate": igst_rate,
                                        "taxable": row.taxable_value or 0,
                                        "cgst_value": cgst_value,
                                        "sgst_value": sgst_value,
                                        "igst_value": igst_value,
                                        "tax": gst_value,
                                        "invoice_value": gst_value + row.taxable_value,
                                    }
                                }) %}
                            {% endif %}



                        {% else %}
                            {% set gst_rate = 0 %}
                        {% endif %}

                        <td style="border: 1px solid #000; text-align: right;"><div style="padding-right: 5px;">{{ gst_rate }}</div></td>
                        <td style="border: 1px solid #000; text-align: right;"><div style="padding-right: 5px;">{{ ("%.2f"|format(gst_value)) }}</div></td>
                        <td style="border: 1px solid #000; text-align: right;"><div style="padding-right: 5px;">{{ ("%.2f"|format(row.taxable_value+gst_value)) }}</div></td>
                    </tr>
                {% endfor %}
            </tbody>
            <!-- <tfoot> -->
                <tr style="font-weight: bold; background-color: #f2f2f2;">
                    <td style="border: 1px solid #000;"></td>
                    <td style="border: 1px solid #000; text-align: right;"><div style="padding-right: 5px;">Total</div></td>
                    <td style="border: 1px solid #000;"></td>
                    <td style="border: 1px solid #000; text-align: right;"><div style="padding-right: 5px;">{{ doc.total_qty }}</div></td>
                    <td style="border: 1px solid #000;"></td>
                    <td style="border: 1px solid #000; text-align: right;"><div style="padding-right: 5px;">{{ ("%.2f"|format(doc.total)) }}</div></td>
                    <td style="border: 1px solid #000;"></td>

                    <td style="border: 1px solid #000; text-align: right;"><div style="padding-right: 5px;">{{ ("%.2f"|format(doc.total_taxes_and_charges)) }}</div></td>
                    <td style="border: 1px solid #000; text-align: right;"><div style="padding-right: 5px;">{{ ("%.2f"|format(doc.grand_total)) if doc.grand_total else 0 }}</div></td>
                </tr>
            <!-- </tfoot> -->
        </table>

        <!-- <pre>{{ ratewise_gst }}</pre>
        <pre>{{ has_igst }}</pre> -->

        <!-- <pre>{{ hsnwise_gst }}</pre> -->




        {% set symbol = 'Rs.' %}
        <table style="border: 1px solid black; width: 100%; border-collapse: collapse; table-layout: fixed; margin-top: 5px;">
            <tr>
                <!-- Left Section -->
                <td style="width: 65%;">
                    <table style="border: 0px solid black; width: 100%; border-collapse: collapse; table-layout: fixed;">
                        <tr>
                            <td colspan="4" style ="border-right: 1px solid #000; border-top: 0; border-left: 0; border-bottom: 1px solid #000; text-align:center;"> Base for Tax Amount</td>
                            <td colspan="4" style="border-right: 1px solid #000; border-top: 0; border-left: 0; border-bottom: 1px solid #000; text-align:center;" > Tax Amount </td>
                        </tr>

                        <tr>
                            <td  style ="width: 12%; border-right: 1px solid #000; border-top: 0; border-left: 0; border-bottom: 0; padding:1px !important;text-align:center;"> Taxable<br>Amount</td>
                            <td style ="width: 12%; border-right: 1px solid #000; border-top: 0; border-left: 0; border-bottom: 0; padding:1px !important;text-align:center;" > IGST<br>(%) </td>
                            <td style ="width: 12%; border-right: 1px solid #000; border-top: 0; border-left: 0; border-bottom: 0; padding:1px !important;text-align:center;" > CGST<br>(%) </td>
                            <td  style ="width: 12%; border-right: 1px solid #000; border-top: 0; border-left: 0; border-bottom: 0; padding:1px !important;text-align:center;"> SGST<br>(%) </td>

                            <td  style ="width: 12%; border-right: 1px solid #000; border-top: 0; border-left: 0; border-bottom: 0; padding:1px !important;text-align:center;"> IGST<br>{{symbol}} </td>
                            <td style ="width: 12%; border-right: 1px solid #000; border-top: 0; border-left: 0; border-bottom: 0; padding:1px !important;text-align:center;"> CGST<br>{{symbol}}</td>
                            <td style ="width: 12%; border-right: 1px solid #000; border-top: 0; border-left: 0; border-bottom: 0; padding:1px !important;text-align:center;"> SGST<br>{{symbol}} </td>
                            <td style ="width: 12%; border-right: 1px solid #000; border-top: 0; border-left: 0; border-bottom: 0; padding:1px !important;text-align:center;">Total<br>{{symbol}} </td>
                        </tr>


                        <!-- <pre>{{ ratewise_gst }}</pre> -->
                        {% for rate, data in ratewise_gst.items() %}
                            {% set total_tax = (data.igst_value + data.cgst_value + data.sgst_value) | round(4) %}
                            <tr>
                                <td style="border-right: 0px solid #000; border-top: 1px solid #000; border-left: 0; border-bottom: 1px solid #000; text-align:right; padding-right:5px !important;">{{ "%.2f"|format(data.taxable) }}</td>

                                <td style="border:1px solid #000; text-align:right; padding-right:5px !important;">{{ data.igst_rate }}</td>
                                <td style="border:1px solid #000; text-align:right; padding-right:5px !important;">{{ data.cgst_rate }}</td>
                                <td style="border:1px solid #000; text-align:right; padding-right:5px !important;">{{ data.sgst_rate }}</td>

                                <td style="border:1px solid #000; text-align:right; padding-right:5px !important;">{{ "%.4f"|format(data.igst_value) }}</td>
                                <td style="border:1px solid #000; text-align:right; padding-right:5px !important;">{{ "%.4f"|format(data.cgst_value) }}</td>
                                <td style="border:1px solid #000; text-align:right; padding-right:5px !important;">{{ "%.4f"|format(data.sgst_value) }}</td>

